function C = read_hs_CA_CM(name)
%(D. Stamenov, Jan 2023 ) This function reads the added mass and damping i.e. CA and CM files generated by Hydrostar 
% and converts it to a user friendly format for use in MATLAB

%Input
%name = name of the file to be loaded should be .rao


%Output
% C.freq = frequency axis [rad/s]
% C.Amplitude = amplitude values (freq, heading)
% C.phi = phase values (freq, heading) [deg]

C_raw = importdata(name,' ' , 22); %22 is lines to skip); 

temp = C_raw.textdata(21);
headings =  textscan(temp{1},'%s','Delimiter',' '); headings = headings{1,1};
headings = headings(~cellfun('isempty', headings)); %remove spaces
clear temp

nh = numel(headings)-1; %number of headings

C.freq = C_raw.data(:,1)'; %extract frequencies
C.headings = headings;
C.dw = C.freq(2)-C.freq(1); %frequency axis increment
for i = 1:nh
    C.val(i,:) = C_raw.data(:,1+i) ; %extract each heading
end

end